#!/usr/bin/env python3
"""Entry program for the make.fun news-image-20261121 submission.

Running this program writes the poster image (entry.png) into the
output directory named by the MAKEFUN_OUTPUT_DIR environment
variable, or into the current working directory when that variable
is not set. The image bytes are embedded below as base64.
"""

import base64
import hashlib
import os
import sys
import tempfile

PNG_B64 = ""

EXPECTED_SHA256 = "2644172b19d5b38d96a21a25fa0ba8007cdbf8c5934df513799d6008999dcdc0"


def main():
    data = base64.b64decode(PNG_B64)
    dest_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or os.getcwd()
    out = os.path.join(dest_dir, "entry.png")
    # Write atomically: temp file in the destination directory, verify
    # the bytes, then os.replace into place. mkstemp creates the temp
    # file mode 0600 and os.replace keeps that mode, so chmod the
    # landed artifact to 0644 — the grader's scorer runs as a
    # different uid and must be able to read entry.png.
    fd, tmp = tempfile.mkstemp(dir=dest_dir, prefix=".entry-", suffix=".tmp")
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(data)
        digest = hashlib.sha256(data).hexdigest()
        if digest != EXPECTED_SHA256:
            raise SystemExit("sha256 mismatch: " + digest)
        os.replace(tmp, out)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise
    os.chmod(out, 0o644)
    print("wrote", out, len(data), "bytes, sha256", digest)
    return 0


if __name__ == "__main__":
    sys.exit(main())
